insert into public.content_items(slug,name_th,name_en,rarity,category,base_value,weight,tags,properties,active)values('phoenix-ember','ประกายเถ้าฟีนิกซ์','Phoenix Ember','soulbound','consumable',0,1,array['solo','revival','soulbound'],'{"revive_hp_percent":50,"tradeable":false}',true);
create table public.solo_life_states(character_id uuid primary key references public.characters(id)on delete cascade,user_id uuid not null references auth.users(id)on delete cascade,status text not null default'alive'check(status in('alive','dead')),death_count integer not null default 0,revival_count integer not null default 0,last_death_location_id bigint references public.world_locations(id),last_cause text,last_died_at timestamptz,last_revived_at timestamptz,updated_at timestamptz not null default now());
create table public.solo_life_events(id uuid primary key default gen_random_uuid(),character_id uuid not null references public.characters(id)on delete cascade,user_id uuid not null references auth.users(id)on delete cascade,solo_adventure_id uuid not null references public.solo_adventures(id)on delete cascade,event_type text not null check(event_type in('defeat','revival')),location_id bigint not null references public.world_locations(id),cause text,item_id bigint references public.content_items(id),hp_after smallint not null,created_at timestamptz not null default now());
alter table public.solo_life_states enable row level security;alter table public.solo_life_events enable row level security;create policy "Players can read their solo life state"on public.solo_life_states for select to authenticated using(user_id=auth.uid());create policy "Players can read their solo life events"on public.solo_life_events for select to authenticated using(user_id=auth.uid());
create or replace function public.grant_starting_revival_item()returns trigger language plpgsql security definer set search_path=''as $$declare item_id bigint;begin select id into item_id from public.content_items where slug='phoenix-ember';insert into public.character_item_stacks(character_id,user_id,content_item_id,quantity,acquired_unit_value)values(new.id,new.user_id,item_id,1,0)on conflict(character_id,content_item_id)do nothing;return new;end;$$;
create trigger characters_grant_revival_item after insert on public.characters for each row execute function public.grant_starting_revival_item();
insert into public.character_item_stacks(character_id,user_id,content_item_id,quantity,acquired_unit_value)select hero.id,hero.user_id,item.id,1,0 from public.characters hero cross join public.content_items item where item.slug='phoenix-ember'on conflict(character_id,content_item_id)do nothing;
create or replace function public.record_solo_defeat(target_character_id uuid,target_cause text default'พ่ายแพ้ในป่า')returns jsonb language plpgsql security definer set search_path=''as $$declare hero public.characters%rowtype;session public.solo_adventures%rowtype;position public.character_world_positions%rowtype;life public.solo_life_states%rowtype;clean_cause text;begin clean_cause:=left(trim(coalesce(target_cause,'')),120);if char_length(clean_cause)<1 then clean_cause:='พ่ายแพ้ในป่า';end if;select*into hero from public.characters where id=target_character_id and user_id=auth.uid()for update;if hero.id is null then raise exception'character not found';end if;select*into session from public.solo_adventures where character_id=hero.id and user_id=auth.uid()and status='active'for update;if session.id is null then raise exception'solo not active';end if;select*into life from public.solo_life_states where character_id=hero.id for update;if life.status='dead'then raise exception'already dead';end if;select*into position from public.character_world_positions where character_id=hero.id;update public.characters set hp_current=0,updated_at=now()where id=hero.id;insert into public.solo_life_states(character_id,user_id,status,death_count,last_death_location_id,last_cause,last_died_at)values(hero.id,auth.uid(),'dead',1,position.location_id,clean_cause,now())on conflict(character_id)do update set status='dead',death_count=public.solo_life_states.death_count+1,last_death_location_id=excluded.last_death_location_id,last_cause=excluded.last_cause,last_died_at=now(),updated_at=now()returning*into life;insert into public.solo_life_events(character_id,user_id,solo_adventure_id,event_type,location_id,cause,hp_after)values(hero.id,auth.uid(),session.id,'defeat',position.location_id,clean_cause,0);return jsonb_build_object('status','dead','hp_current',0,'death_count',life.death_count,'cause',clean_cause,'location_id',position.location_id);end;$$;
create or replace function public.revive_solo_character(target_character_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare hero public.characters%rowtype;session public.solo_adventures%rowtype;position public.character_world_positions%rowtype;life public.solo_life_states%rowtype;item public.content_items%rowtype;stack public.character_item_stacks%rowtype;restored_hp integer;remaining integer;begin select*into hero from public.characters where id=target_character_id and user_id=auth.uid()for update;if hero.id is null then raise exception'character not found';end if;select*into session from public.solo_adventures where character_id=hero.id and user_id=auth.uid()and status='active'for update;if session.id is null then raise exception'solo not active';end if;select*into life from public.solo_life_states where character_id=hero.id and user_id=auth.uid()for update;if life.status is distinct from'dead'then raise exception'character not dead';end if;select*into item from public.content_items where slug='phoenix-ember';select*into stack from public.character_item_stacks where character_id=hero.id and content_item_id=item.id for update;if stack.id is null or stack.quantity<1 then raise exception'revival item required';end if;remaining:=stack.quantity-1;if remaining=0 then delete from public.character_item_stacks where id=stack.id;else update public.character_item_stacks set quantity=remaining,updated_at=now()where id=stack.id;end if;restored_hp:=greatest(1,(hero.hp_max+1)/2);update public.characters set hp_current=restored_hp,updated_at=now()where id=hero.id;update public.solo_life_states set status='alive',revival_count=revival_count+1,last_revived_at=now(),updated_at=now()where character_id=hero.id returning*into life;select*into position from public.character_world_positions where character_id=hero.id;insert into public.solo_life_events(character_id,user_id,solo_adventure_id,event_type,location_id,item_id,hp_after)values(hero.id,auth.uid(),session.id,'revival',position.location_id,item.id,restored_hp);return jsonb_build_object('status','alive','hp_current',restored_hp,'hp_max',hero.hp_max,'revival_count',life.revival_count,'item_remaining',remaining,'location_id',position.location_id);end;$$;
create or replace function public.end_solo_adventure(target_character_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare session public.solo_adventures%rowtype;begin if exists(select 1 from public.solo_life_states where character_id=target_character_id and user_id=auth.uid()and status='dead')then raise exception'revival required';end if;update public.solo_adventures set status='ended',ended_at=now()where character_id=target_character_id and user_id=auth.uid()and status='active'returning*into session;if session.id is null then raise exception'solo not active';end if;return jsonb_build_object('id',session.id,'character_id',session.character_id,'status',session.status,'ended_at',session.ended_at);end;$$;
create or replace function public.enforce_solo_wilderness()returns trigger language plpgsql security definer set search_path=''as $$declare destination_type text;begin if exists(select 1 from public.solo_life_states where character_id=new.character_id and status='dead')then raise exception'solo character dead';end if;if exists(select 1 from public.solo_adventures where character_id=new.character_id and status='active')then select location_type into destination_type from public.world_locations where id=new.location_id;if destination_type<>'wilderness'then raise exception'solo wilderness only';end if;end if;return new;end;$$;
revoke all on function public.record_solo_defeat(uuid,text)from public;revoke all on function public.revive_solo_character(uuid)from public;grant execute on function public.record_solo_defeat(uuid,text)to authenticated;grant execute on function public.revive_solo_character(uuid)to authenticated;
